import csv
import json
from datetime import date, timedelta, datetime
from decimal import Decimal

FACT_MAPPING = {
    "lca.wage_105": {
        "offered wage": ("lca_disclosure", "WAGE_RATE_OF_PAY_FROM", "amount"),
        "prevailing wage": ("lca_disclosure", "PREVAILING_WAGE", "amount"),
    },
    "lca.three_years": {
        "begin date": ("lca_disclosure", "BEGIN_DATE", "date"),
        "end date": ("lca_disclosure", "END_DATE", "date"),
    }
}

doc_cache = {}

def find_file(packet_dir, doc_name):
    for fname in os.listdir(packet_dir):
        base, ext = os.path.splitext(fname)
        if base.lower() == doc_name.lower():
            return os.path.join(packet_dir, fname)
    return None

def get_doc_data(packet_dir, doc_name):
    if doc_name in doc_cache:
        return doc_cache[doc_name]
    fpath = find_file(packet_dir, doc_name)
    if not fpath:
        doc_cache[doc_name] = {}
        return {}

    entity_rows = {}
    with open(fpath, mode='r', encoding='utf-8', errors='replace') as f:
        reader = csv.DictReader(f)
        for row in reader:
            clean_row = {k.strip(): (v.strip() if v is not None else "") for k, v in row.items() if k}
            case_num = clean_row.get("CASE_NUMBER", "")
            if case_num:
                entity_rows.setdefault(case_num, []).append(clean_row)
    doc_cache[doc_name] = entity_rows
    return entity_rows

def parse_date(val):
    val = val.strip()
    if not val:
        return None
    for fmt in ('%Y-%m-%d', '%m/%d/%Y', '%d/%m/%Y', '%Y/%m/%d', '%B %d, %Y', '%b %d, %Y'):
        try:
            return datetime.strptime(val, fmt).strftime('%Y-%m-%d')
        except ValueError:
            pass
    try:
        num = float(val)
        if 20000 <= num <= 90000:
            dt = date(1899, 12, 30) + timedelta(days=int(round(num)))
            return dt.strftime('%Y-%m-%d')
    except ValueError:
        pass
    return val

def parse_amount(val):
    clean = val.strip().replace('$', '').replace(',', '')
    if not clean:
        return None, None
    try:
        d = Decimal(clean)
        return clean, d
    except Exception:
        return clean, clean

def extract_fact_value(packet_dir, rule_id, fact_name, entity):
    rule_spec = FACT_MAPPING.get(rule_id, {})
    if fact_name not in rule_spec:
        return "ABSENT"
    doc_name, field_name, val_type = rule_spec[fact_name]
    doc_data = get_doc_data(packet_dir, doc_name)
    rows = doc_data.get(entity, [])
    if not rows:
        return "ABSENT"

    seen_values = {}
    for r in rows:
        raw_val = r.get(field_name, "").strip()
        if not raw_val:
            continue
        if val_type == "date":
            norm = parse_date(raw_val)
            if norm:
                seen_values[norm] = norm
        elif val_type == "amount":
            clean, comp_key = parse_amount(raw_val)
            if clean is not None:
                seen_values[comp_key] = clean
        else:
            seen_values[raw_val] = raw_val

    if len(seen_values) == 0:
        return "ABSENT"
    elif len(seen_values) > 1:
        return "CONFLICT"
    else:
        out_val = next(iter(seen_values.values()))
        return [out_val, doc_name]

def main():
    if len(sys.argv) < 3:
        sys.exit(1)
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, mode='r', encoding='utf-8') as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts_spec = manifest.get("facts", {})

    output = {}
    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        facts = facts_spec.get(rule_id, [])
        pair_result = {}
        for fact in facts:
            pair_result[fact] = extract_fact_value(packet_dir, rule_id, fact, entity)
        output[pair] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

