import csv
import datetime
from decimal import Decimal
import json
import os
import sys

FACT_MAP = {
    "offered wage": ("WAGE_RATE_OF_PAY_FROM", "amount"),
    "prevailing wage": ("PREVAILING_WAGE", "amount"),
    "begin date": ("BEGIN_DATE", "date"),
    "end date": ("END_DATE", "date"),
    "job title": ("JOB_TITLE", "string"),
    "soc code": ("SOC_CODE", "string"),
    "soc title": ("SOC_TITLE", "string"),
    "full time position": ("FULL_TIME_POSITION", "string"),
    "worksite city": ("WORKSITE_CITY", "string"),
    "worksite state": ("WORKSITE_STATE", "string"),
    "pw wage level": ("PW_WAGE_LEVEL", "string"),
    "wage level": ("PW_WAGE_LEVEL", "string"),
    "wage rate of pay to": ("WAGE_RATE_OF_PAY_TO", "amount"),
    "offered wage to": ("WAGE_RATE_OF_PAY_TO", "amount"),
}


def parse_date(val):
    if not val:
        return None
    val = val.strip()
    if not val:
        return None
    if len(val) == 10 and val[4] == "-" and val[7] == "-":
        try:
            datetime.date.fromisoformat(val)
            return val
        except ValueError:
            pass
    try:
        f = float(val)
        if 1000 <= f <= 100000:
            dt = datetime.date(1899, 12, 30) + datetime.timedelta(
                days=int(round(f))
            )
            return dt.isoformat()
    except ValueError:
        pass

    for fmt in (
        "%Y-%m-%d",
        "%m/%d/%Y",
        "%d/%m/%Y",
        "%Y/%m/%d",
        "%m-%d-%Y",
        "%Y%m%d",
    ):
        try:
            return datetime.datetime.strptime(val, fmt).date().isoformat()
        except ValueError:
            pass
    return None


def parse_amount(val):
    if not val:
        return None
    val = val.strip().replace("$", "").replace(",", "")
    if not val:
        return None
    try:
        d = Decimal(val)
        if d == d.to_integral():
            return str(d.to_integral())
        return str(d)
    except Exception:
        return None


def parse_string(val):
    if not val:
        return None
    val = val.strip()
    return val if val else None


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    doc_name = "lca_disclosure"
    file_path = None
    for fname in os.listdir(packet_dir):
        name, ext = os.path.splitext(fname)
        if name.lower() == "lca_disclosure":
            file_path = os.path.join(packet_dir, fname)
            doc_name = name
            break

    records_by_entity = {}
    if file_path and os.path.exists(file_path):
        with open(file_path, "r", encoding="utf-8-sig", errors="replace") as f:
            reader = csv.DictReader(f)
            for row in reader:
                case_number = row.get("CASE_NUMBER")
                if case_number:
                    case_number = case_number.strip()
                    records_by_entity.setdefault(case_number, []).append(row)

    output = {}
    manifest_facts = manifest.get("facts", {})

    for pair in manifest.get("pairs", []):
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        facts_for_rule = manifest_facts.get(rule_id, [])

        pair_result = {}
        rows = records_by_entity.get(entity, [])

        for fact in facts_for_rule:
            fact_key = fact.strip().lower()
            mapping = FACT_MAP.get(fact_key)

            if not mapping:
                pair_result[fact] = "ABSENT"
                continue

            col_name, val_type = mapping
            values = []

            for row in rows:
                raw_val = row.get(col_name)
                if val_type == "date":
                    parsed = parse_date(raw_val)
                elif val_type == "amount":
                    parsed = parse_amount(raw_val)
                else:
                    parsed = parse_string(raw_val)

                if parsed is not None:
                    values.append(parsed)

            if not values:
                pair_result[fact] = "ABSENT"
            else:
                if val_type == "amount":
                    first_dec = Decimal(values[0])
                    has_conflict = any(Decimal(v) != first_dec for v in values)
                else:
                    first_val = values[0]
                    has_conflict = any(v != first_val for v in values)

                if has_conflict:
                    pair_result[fact] = "CONFLICT"
                else:
                    pair_result[fact] = [values[0], doc_name]

        output[pair] = pair_result

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()

