import csv
import datetime
import json
import os
import sys


def parse_date(val):
    if not val:
        return None
    val = str(val).strip()
    if not val:
        return None

    # Check for Excel serial date
    try:
        f = float(val)
        if 1 <= f <= 100000:
            d = datetime.date(1899, 12, 30) + datetime.timedelta(days=int(round(f)))
            return d.strftime("%Y-%m-%d")
    except ValueError:
        pass

    for fmt in [
        "%Y-%m-%d",
        "%Y-%m-%d %H:%M:%S",
        "%m/%d/%Y",
        "%m/%d/%Y %H:%M:%S",
        "%m-%d-%Y",
        "%d/%m/%Y",
        "%Y/%m/%d",
        "%B %d, %Y",
        "%b %d, %Y",
        "%d-%b-%Y",
        "%d-%B-%Y",
    ]:
        try:
            dt = datetime.datetime.strptime(val, fmt)
            return dt.strftime("%Y-%m-%d")
        except ValueError:
            pass

    return val


def parse_amount(val):
    if not val:
        return None
    val = str(val).strip()
    if not val:
        return None
    if val.startswith("(") and val.endswith(")"):
        val = "-" + val[1:-1].strip()
    val = val.replace("$", "").replace(",", "").strip()
    return val


def normalize_value(fact_name, val):
    fact_lower = fact_name.lower()
    if "date" in fact_lower:
        return parse_date(val)
    elif any(k in fact_lower for k in ["wage", "amount", "pay", "salary"]):
        return parse_amount(val)
    return val.strip() if val else None


def load_records(packet_dir):
    records_by_doc = {}
    if not os.path.isdir(packet_dir):
        return records_by_doc

    for fname in os.listdir(packet_dir):
        if fname.lower().endswith(".csv"):
            doc_name = os.path.splitext(fname)[0]
            fpath = os.path.join(packet_dir, fname)
            with open(fpath, "r", encoding="utf-8-sig", errors="replace") as f:
                reader = csv.DictReader(f)
                rows = []
                for row in reader:
                    cleaned_row = {
                        (k.strip() if k else ""): (v.strip() if v else "")
                        for k, v in row.items()
                    }
                    rows.append(cleaned_row)
                records_by_doc[doc_name] = rows
    return records_by_doc


FACT_MAPPING = {
    "offered wage": ("lca_disclosure", ["WAGE_RATE_OF_PAY_FROM"]),
    "prevailing wage": ("lca_disclosure", ["PREVAILING_WAGE"]),
    "begin date": ("lca_disclosure", ["BEGIN_DATE"]),
    "end date": ("lca_disclosure", ["END_DATE"]),
}


def get_fact_location(fact_name):
    fact_key = fact_name.lower().strip()
    if fact_key in FACT_MAPPING:
        return FACT_MAPPING[fact_key]
    col_name = fact_key.upper().replace(" ", "_")
    return ("lca_disclosure", [col_name])


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    records_by_doc = load_records(packet_dir)

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity_id = pair.split("::", 1)
        facts_list = facts_by_rule.get(rule_id, [])

        pair_result = {}
        for fact_name in facts_list:
            doc_name, col_candidates = get_fact_location(fact_name)
            rows = records_by_doc.get(doc_name, [])

            # Filter rows for this entity
            entity_rows = [
                r for r in rows if r.get("CASE_NUMBER", "").strip() == entity_id
            ]

            observed_values = set()
            for r in entity_rows:
                raw_val = None
                for col in col_candidates:
                    if col in r and r[col]:
                        raw_val = r[col]
                        break

                if raw_val is not None and raw_val != "":
                    norm_val = normalize_value(fact_name, raw_val)
                    if norm_val is not None and norm_val != "":
                        observed_values.add(norm_val)

            if len(observed_values) == 0:
                pair_result[fact_name] = "ABSENT"
            elif len(observed_values) == 1:
                pair_result[fact_name] = [next(iter(observed_values)), doc_name]
            else:
                pair_result[fact_name] = "CONFLICT"

        output[pair] = pair_result

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()

